  # 전체 셀의 동일96픽셀 축척. 낱부위 확대/축소나 옛 픽셀 덮기는 없다.
  native=register(cell,(96,96),pal,'area_vote');yy,xx=np.nonzero((native==14)&(np.indices(native.shape)[0]<58));need(len(xx),'Pupil');sy=int(yy.min());sx=int(np.median(xx[yy==sy]));old=np.array(Image.open(inputs/f'before_{n:03}_indices.png'));oy,ox=np.nonzero(old==14);ey=int(oy.min()-160);ex=int(np.median(ox[oy==oy.min()])-160);dx=ex-(sx-48);dy=ey-(sy-48);need(abs(dx)<=4 and abs(dy)<=4,'Unexpected source drift');target=np.zeros((384,384),np.uint8);target[112+dy:208+dy,112+dx:208+dx]=native;Image.fromarray(target).save(out/f'before_{n:03}.png');a.rgba(target,16).save(out/f'before_{n:03}_rgba.png');yy,xx=np.nonzero(target);y0,x0,y1,x1=int(yy.min()-160),int(xx.min()-160),int(yy.max()+1-160),int(xx.max()+1-160);need(x1-x0<80 and y1-y0<80,'Sprite size');q=plan[n,'before']
