 helper.grid(rows,out/'comparison.png',6);write(out/'registration.json',{'source_arc_sha256':digest(src),'source_art_sha256':digest(art),'frames':recs,'method':'고정96px셀 area_vote, 전체 평행이동으로 눈 좌표 정합. 몸/다리/머리의 개별 축척 변경이나 옛 픽셀 덮기 없음. 발끝/권총/연속성 미확인 후보.','native_packed':False,'runtime_verified':False});write(art.parent/'generation.json',{'mode':'builtin image_gen edit','source_generated_path':args.generated_path,'workspace_path':art.relative_to(ROOT).as_posix(),'workspace_sha256':digest(art),'image_size':list(im.size),'input_images':{p.name:digest(p)for p in inputs.glob('*.png')if 'targets'in p.name or 'reference'in p.name or 'style'in p.name or 'motion_only'in p.name},'prompt_spec':(D/args.prompt).relative_to(ROOT).as_posix(),'prompt_spec_sha256':digest(D/args.prompt),'prompt_note':'첫페이지 명세는 별도 정리이며 후속페이지는 저장파일을 실제 builtin prompt로 전달.','palette_requantized_only_in_separate_native_candidates':True,'original_generated_file_unmodified':True});print(json.dumps({'sha256':digest(art),'frames':recs},ensure_ascii=False))
